const c = $('Recetas').first().json;
const r = $input.first().json;

if (!Array.isArray(r.data) || r.data.length !== c.recetas.length) {
  throw new Error('La cantidad de embeddings no coincide con la cantidad de recetas');
}

const points = c.recetas.map((receta, i) => ({
  id: receta.id,
  vector: r.data[i].embedding,
  payload: { nombre: receta.nombre, ingredientes: receta.ingredientes, pasos: receta.pasos }
}));

return [{ json: { qdrant_url: c.qdrant_url, coleccion: c.coleccion, vector_size: points[0].vector.length, points } }];
